import React, { useEffect, useState } from 'react'
import MenusTable from './MenusTable'

import useApi from '../../../hooks/useApi'
import { useNavigate } from 'react-router-dom';
import MenuFormModal from './MenuFormModal';
import { ToastContainer, toast } from "react-toastify";
import restaurantApi from '../../../api/restaurants/restaurantApi';

const columns = [

    { name: "Title", uid: "title" },
    { name: "Entity", uid: "entity_title" },
    { name: "Branch", uid: "branch_title" },
    { name: "Served On", uid: "served_on" },
    { name: "Served From", uid: "served_from" },
    { name: "Served To", uid: "served_to" },
    { name: "Description", uid: "description" },
    { name: "Actions", uid: "actions" },
];


function MenusList() {
    const [openEditModal, setopenEditModal] = useState(false)

    const navigate = useNavigate()
    const [menu, setMenu] = useState()
    const [menus, setMenus] = useState([])
    const [data, setdata] = useState([])
    const [updated, setUpdated] = useState(false)
    const [modalTitle, setmodalTitle] = useState("")
    const restaurantActionsApi = useApi(restaurantApi.restaurantAction)
    const [errors, setErrors] = useState([]);
    const getOutletMenus = async () => {
        await restaurantActionsApi.request({
          action: "GetBranchMenus",
        });
    }
    useEffect(() => {
        setdata(menus)
    }, [menus])

    const handleFilter = (e) => {

        console.log('eeeee', e)
        const search_param = e

        if (menus && menus.length > 0 && search_param && search_param !== '') {
            setdata(menus.filter((x) => x.title.toLowerCase().includes(search_param)));
        } else {
            setdata(menus);
        }
    };

    useEffect(() => {
        getOutletMenus()
    }, [])

    useEffect(() => {

  
              getOutletMenus()
        
      
    }, [updated])

    const handleEditAction = (item) => {

        setopenEditModal(true)
        setMenu(item)
        setmodalTitle(`Edit ${item.title}`)
        setUpdated(false)

    }

    const handleAddAction = () => {
        setUpdated(false)
        setopenEditModal(true)
        setmodalTitle("Add new menu")
        setMenu(null)
    }
    const handleDetailsAction = (item) => {


        navigate(`/routes/details/${item.id}`, {
            state: {
                'item': item
            }
        })
    }
    const handleDeleteAction = (item) => {
        console.log('Item', item)
        navigate(`/routes/delete/${item.id}`)
    }

    useEffect(() => {
        if (errors && errors.length) {
            errors.map((x) => {
                toast.error(x);
            });
        }
    }, [errors]);

    useEffect(() => {

        if (restaurantActionsApi.data && restaurantActionsApi.data.length) {

            setMenus(restaurantActionsApi.data)
        }

        if (restaurantActionsApi.data && restaurantActionsApi.data.response_message && restaurantActionsApi.data.response_code===1) {

            toast.error(restaurantActionsApi.data.response_message)
        }

        if (restaurantActionsApi.data && restaurantActionsApi.data.response_message && restaurantActionsApi.data.response_code===0) {

            toast.success(restaurantActionsApi.data.response_message)
        }
       
        console.log("restaurantActionsApi.data",restaurantActionsApi.data)
    }, [restaurantActionsApi.data])

    useEffect(() => {
        getOutletMenus()
    }, [updated])

    return (
      <div>
        <ToastContainer position="bottom-center" theme="colored" />
        {openEditModal && (
          <MenuFormModal
            ismodalOpen={openEditModal}
            setisModalOpen={setopenEditModal}
            menuToEdit={menu}
            updated={updated}
            setUpdated={setUpdated}
            modalTitle={modalTitle}
          />
        )}
        <MenusTable
          data={data}
          columns={columns}
          editAction={handleEditAction}
          detailsAction={handleDetailsAction}
          deleteAction={handleDeleteAction}
          addAction={handleAddAction}
          handleFilter={handleFilter}
        />
      </div>
    );
}

export default MenusList