import React, { useEffect, useState } from "react";
import * as Yup from "yup";
import { Button } from "@heroui/react";
import {
  CustomForm,
  CustomFormItem,
  CustomInput,
  CustomSelectReactSelect,
  CustomTextArea,
  CustomTimePicker,
  Loading,
} from "../../../components";
import { useFormik } from "formik";
import useApi from "../../../hooks/useApi";
import makeAnimated from "react-select/animated";
import { ToastContainer, toast } from "react-toastify";
import restaurantApi from "../../../api/restaurants/restaurantApi";
import { Modal } from "antd";

export default function MenuFormModal({
  ismodalOpen,
  setisModalOpen,
  menuToEdit,
  modalTitle = "Add new menu",
  updated,
  setUpdated,
}) {
  // const { isOpen, onOpen, onOpenChange } = useDisclosure();
  const animatedComponent = makeAnimated();
  const [menu, setMenu] = useState(menuToEdit ? menuToEdit : null);

  console.log("Item at modal", menuToEdit);


  const restaurantActionsApi = useApi(restaurantApi.restaurantAction);



  const [errors, setErrors] = useState([]);

  const handleMenuAction = async (data) => {
    console.log("data at", data);
    const result = await restaurantActionsApi.request(data);

    if (result.ok) {
      console.log("res", result);
      setUpdated(true);
      setisModalOpen(false);
      // setErrors(result.data.errors)
    } else {
      setUpdated(false);
    }
  };

  useEffect(() => {}, [menu]);

  useEffect(() => {
    if (restaurantActionsApi.data) {
      if (restaurantActionsApi.data.errors) {
        setErrors(restaurantActionsApi.data.errors);
      }

      if (restaurantActionsApi.data.branch_menu) {
        setisModalOpen(false);
        setUpdated(true);
      }
    }

    console.log("restaurantActionsApi.data", restaurantActionsApi.data);
  }, [restaurantActionsApi.data]);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  const formik = useFormik({
    initialValues: {
      served_on: menu ? menu.served_on : "",
      // served_from: menu ? menu.served_from : "00:00",
      // served_to: menu ? menu.served_to :"00:00",
      description: menu ? menu.description : "",
    },

    validationSchema: Yup.object({
      served_on: Yup.object().required("Days menu is served is required"),
    }),
    onSubmit: (values, { resetForm }) => {
      //Dispatch action

      console.log("VALZ", values);
      setErrors([]);

      if (menuToEdit) {
        handleMenuAction({
          action: "UpdateBranchMenu",
          menu_details: {
            menu: menu.id,
            served_on: values.served_on.value,
            served_from: values.served_from,
            served_to: values.served_to,
            title: values.title,
            description: values.description ? values.description : "",
          },
        });
      } else {
        handleMenuAction({
          action: "CreateBranchMenu",
          menu_details: {
            title: values.title,
            served_on: values.served_on.value,
            served_from: values.served_from,
            served_to: values.served_to,
            description: values.description ? values.description : "",
          },
        });
      }

      // resetForm();
    },
  });

  const handleServedFromChange = (time, timeString) => {
    console.log("timeString", timeString);
    formik.setFieldValue("served_from", timeString);
  };

  const handleServedToChange = (time, timeString) => {
    console.log("timeString", timeString);
    formik.setFieldValue("served_to", timeString);
  };

  const handleOk = () => {
    setisModalOpen(false);
  };
  const handleCancel = () => {
    setisModalOpen(false);
  };

  return (
    <div className="w-full">
      <Modal
        width={500}
        className="w-full text-center"
        title={modalTitle}
        open={ismodalOpen}
        onOk={handleOk}
        onCancel={handleCancel}
        cancelButtonProps={{ style: { display: "none" } }}
        okButtonProps={{ style: { display: "none" } }}
      >
        <ToastContainer theme="colored" position="bottom-center" />
        <CustomForm
          layout="vertical"
          handleFinish={formik.handleSubmit}
          className=" flex flex-col justify-center items-center w-full"
        >
          <div className="w-full grid grid-cols-1 mt-5 gap-1 ">
            <CustomFormItem
              touched={formik.touched.title}
              error={formik.errors.title}
            >
              <CustomInput
                required={true}
                label="Enter title"
                id="title"
                name="title"
                onChange={formik.handleChange}
                placeholder="Enter menu title"
                size="large"
                type="text"
                value={formik.values.title}
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.served_on}
              error={formik.errors.served_on}
            >
              <CustomSelectReactSelect
                className="text-start"
                name="served_on"
                id="served_on"
                label="Select served_on"
                size="large"
                onChange={(value) => formik.setFieldValue("served_on", value)}
                value={formik.values.county}
                placeholder="Which day is the menu served?"
                options={[
                  { label: "DAILY", value: "DAILY" },
                  { label: "MONDAY", value: "MONDAY" },
                  { label: "TUESDAY", value: "TUESDAY" },
                  { label: "WEDNESDAY", value: "WEDNESDAY" },
                  { label: "THURSDAY", value: "THURSDAY" },
                  { label: "FRIDAY", value: "FRIDAY" },
                  { label: "SATURDAY", value: "SATURDAY" },
                  { label: "SUNDAY", value: "SUNDAY" },
                ]}
              />
            </CustomFormItem>
            <CustomFormItem
              touched={formik.touched.served_from}
              error={formik.errors.served_from}
            >
              <CustomTimePicker
                id="served_from"
                defaultValue={formik.values.served_from}
                name="served_from"
                size="large"
                placeholder="Select served from time"
                onChange={handleServedFromChange}
                value={formik.values.served_from}
                label="Select served from time"
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.served_to}
              error={formik.errors.served_to}
            >
              <CustomTimePicker
                id="served_to"
                defaultValue={formik.values.served_to}
                name="served_to"
                size="large"
                placeholder="Select served to time"
                onChange={handleServedToChange}
                value={formik.values.served_to}
                label="Select served to time"
              />
            </CustomFormItem>

            <CustomFormItem
              touched={formik.touched.description}
              error={formik.errors.description}
            >
              <CustomTextArea
                maxLength={48}
                required={true}
                label="Type short description"
                id="description"
                name="description"
                onChange={formik.handleChange}
                placeholder="Enter description"
                size="large"
                type="text"
                value={formik.values.description}
              />
            </CustomFormItem>
          </div>
          <div className="w-full items-center mt-2">
            <Button className="w-36 rounded-md" color="primary" type="submit">
              Submit
            </Button>
          </div>
        </CustomForm>
      </Modal>
    </div>
  );
}
